function navigate(name){
 if(name==='overview'){contentRoot.innerHTML=dashboardMarkup;}else{contentRoot.innerHTML=screens[name==='vision-lab'?'vision-labs':name]||dashboardMarkup;}
 document.querySelectorAll('.nav-item[data-screen]').forEach(a=>a.classList.toggle('active',a.dataset.screen===name));
 document.querySelector('.crumb').innerHTML=`My workspace <span>/</span> ${screenNames[name]||'Overview'}`;
 history.replaceState(null,'','#'+name);
 window.scrollTo({top:0,behavior:'smooth'});
 if(name==='vision-labs'||name==='vision-lab'){renderCvLabs();loadVisionProgress();}
 if(name==='drawing')checkDrawingService();
}
document.addEventListener('click',e=>{
 const link=e.target.closest('[data-screen]'); if(link){e.preventDefault();if(modal.classList.contains('open'))closeModal();navigate(link.dataset.screen);return;}
 if(e.target.closest('[data-challenge]')){startChallenge();return;}
 if(e.target.closest('.top-avatar')){navigate('onboarding');return;}
 
 if(e.target.id==='raiseHand')e.target.textContent=e.target.textContent.includes('Lower')?'✋ Raise hand':'✓ Hand raised';
 if(e.target.id==='pollBtn')openModal('<h2 id="modalTitle">Quick poll</h2><p>The target is greater than the midpoint. Which side should we inspect?</p><div class="question"><button class="answer" data-answer="wrong">Left</button><button class="answer" data-answer="right">Right</button></div><div id="answerFeedback"></div>');
 if(['roleStudent','roleTeacher','roleAdmin'].includes(e.target.id)){e.target.closest('.onboarding-card').innerHTML='<div class="brand-icon">✓</div><h1>Your learning space is ready.</h1><p>This prototype starts with a student view. Choose Course catalog or 3D Campus from the sidebar to explore.</p><div class="onboard-actions"><button data-screen="overview">Go to my dashboard</button></div>';}
});
document.addEventListener('input',e=>{if(e.target.id==='courseSearch'){const q=e.target.value.toLowerCase();document.querySelectorAll('#courseGrid .course-tile').forEach(card=>card.hidden=!card.innerText.toLowerCase().includes(q));}});
document.addEventListener('change',e=>{if(e.target.id==='levelFilter'){document.querySelectorAll('#courseGrid .course-tile').forEach(card=>card.hidden=e.target.value!=='all'&&!card.innerText.toLowerCase().includes(e.target.value.toLowerCase()));}});

const API_BASE = 'http://127.0.0.1:4173/api';
async function apiRequest(path, options={}) {
  const response=await fetch(`${API_BASE}${path}`,{headers:{'Content-Type':'application/json',...(options.headers||{})},...options});
  const data=await response.json();
  if(!response.ok)throw new Error(data.error||'API request failed');
  return data;
}
async function loadCatalog(query='',level='all'){
  const grid=document.querySelector('#courseGrid');if(!grid)return;
  try{
    const data=await apiRequest(`/courses?q=${encodeURIComponent(query)}&level=${encodeURIComponent(level)}`);
    grid.innerHTML=data.courses.map(c=>courseCard(c.id==='dsa-binary-search'?'':c.id==='ml-foundations'?'teal':'orange',c.icon,c.category,c.title,c.description,c.duration,c.level)).join('')||'<p class="panel-copy">No courses match those filters.</p>';
  }catch{grid.insertAdjacentHTML('beforebegin','<p class="api-notice">Course API unavailable. Showing the sample catalog.</p>');}
}
async function loadProfileData(){
  try{
    const [{profile},{progress}]=await Promise.all([apiRequest('/profile'),apiRequest('/progress')]);
    const id=document.querySelector('#profileId');if(id)id.textContent=profile.role==='teacher'?'EV-TEACH-DEMO-001':(profile.accountId||profile.id);const age=document.querySelector('#profileAge');if(age)age.textContent=profile.age||'Not provided';const org=document.querySelector('#profileOrg');if(org)org.textContent=profile.institution||'Not linked';const joined=document.querySelector('#profileJoined');if(joined&&profile.joinedAt)joined.textContent=new Date(profile.joinedAt+'T12:00:00').toLocaleDateString(undefined,{year:'numeric',month:'long',day:'numeric'});
    const name=document.querySelector('.profile-hero h2');if(name)name.textContent=profile.name;
    const bio=document.querySelector('.profile-hero p');if(bio)bio.textContent=profile.bio;
    const metrics=document.querySelectorAll('.metric-card strong');if(metrics[1])metrics[1].textContent=`${progress.streakDays} days`;
    const boundary=document.querySelectorAll('.concept')[1];if(boundary){boundary.querySelector('.mastery span').style.width=`${progress.concepts['search-boundaries'].mastery}%`;boundary.querySelector('strong').textContent=`${progress.concepts['search-boundaries'].mastery}%`;}
  }catch{}
}
// Load course and profile data whenever their screens are opened.
async function loadTwinData(){try{const [{progress},{vision}]=await Promise.all([apiRequest('/progress'),apiRequest('/vision/progress')]);const concepts=progress.concepts;const rows=[...document.querySelectorAll('.twin-row')];const keys=['sorted-arrays','search-boundaries','time-complexity'];rows.forEach((row,i)=>{const concept=concepts[keys[i]];if(!concept)return;row.querySelector('.mastery span').style.width=`${concept.mastery}%`;row.querySelector('strong').textContent=`${concept.mastery}%`;row.querySelector('.concept-text small').textContent=`Evidence from ${concept.evidenceCount} practice checks`;});const stat=document.querySelector('.twin-stat strong');if(stat)stat.textContent=Object.keys(concepts).length;const evidence=document.querySelector('.twin-stat small');if(evidence)evidence.textContent=`from ${Object.values(concepts).reduce((n,c)=>n+c.evidenceCount,0)} practice signals`;const count=Object.keys(vision.completed||{}).length,box=document.querySelector('#visionTwinProgress');if(box)box.innerHTML=`<div class="cv-sample-row"><b>Vision experiments completed</b><span>${count}</span></div>${(vision.badges||[]).map(b=>`<div class="cv-sample-row"><b>🏅 ${safeText(b.title)}</b><span>Earned</span></div>`).join('')||'<small>Complete an experiment to earn your first badge.</small>'}`;}catch{const box=document.querySelector('#visionTwinProgress');if(box)box.textContent='Start the local EduVerse API to sync Vision Lab progress.';}}

const originalNavigate=navigate;
navigate=function(name){originalNavigate(name);if(name==='catalog')loadCatalog();if(name==='profile')loadProfileData();if(name==='twin')loadTwinData();};
