const pathMeta={web:{summary:'From your first page to a deployed interactive website.',capstone:'Build an accessible course landing page with a working search and saved progress.'},dsa:{summary:'Learn to choose a data structure and explain why an algorithm works.',capstone:'Create a visual algorithm playground with sorting and search controls.'},backend:{summary:'Design small, reliable services that store and move useful data.',capstone:'Ship a learning tracker API with validated routes and persistent storage.'}};
async function loadNotes(){try{const {notes}=await apiRequest('/notes');if(notes[0]){document.querySelector('#noteTitle').value=notes[0].title;document.querySelector('#noteContent').innerText=notes[0].content;document.querySelector('#noteStatus').textContent=`Saved · ${new Date(notes[0].updatedAt).toLocaleString()}`;}}catch{const local=JSON.parse(localStorage.getItem('eduverse-note')||'null');if(local){document.querySelector('#noteTitle').value=local.title;document.querySelector('#noteContent').innerText=local.content;}document.querySelector('#noteStatus').textContent='API offline · notes stay in this browser view';}}
async function loadSyllabus(pathId='web'){
 try{const {tracks}=await apiRequest('/syllabus');const track=tracks.find(t=>t.id===pathId);if(!track)return;document.querySelector('#pathTitle').textContent=track.title;document.querySelector('#pathSummary').textContent=pathMeta[pathId].summary;document.querySelector('#capstoneText').textContent=pathMeta[pathId].capstone;document.querySelector('#syllabusModules').innerHTML=track.modules.map((m,i)=>`<div class="module-row"><span class="module-number">${String(i+1).padStart(2,'0')}</span><div><b>${m}</b><small>${i<2?'Concepts + guided practice':'Interactive lesson + mini project'}</small></div><span class="module-state">${i===0?'START HERE':'○'}</span></div>`).join('');}catch{document.querySelector('#syllabusModules').innerHTML='<p class="panel-copy">Start the EduVerse API to load coding paths.</p>';}
}
