async function loadTeacherWorkspace(){try{const {teacherData,roster}=await apiRequest('/teacher');const rosterEl=document.querySelector('#attendanceRoster');if(rosterEl)rosterEl.innerHTML=roster.map(s=>`<label class="attendance-person"><span><b>${safeText(s.name)}</b><small>${safeText(s.id)}</small></span><select data-student-id="${safeText(s.id)}"><option value="present" ${s.status==='present'?'selected':''}>Present</option><option value="absent" ${s.status==='absent'?'selected':''}>Absent</option><option value="late">Late</option></select></label>`).join('');renderTeacherRecords('scheduleList',teacherData.schedule,'title','date');renderTeacherRecords('practiceList',teacherData.practice,'topic','question');renderTeacherRecords('testList',teacherData.tests,'title','duration');}catch{const target=document.querySelector('#attendanceRoster');if(target)target.innerHTML='<p class="api-notice">Class tools will load when the local API is running.</p>';}}
