const OPENCV_URL='http://127.0.0.1:4174';
let drawingStream=null,drawingPrevious=null,drawingPaused=false,trackerBusy=false,drawingLoop=0;
function setDrawingStatus(message,online=false){const label=document.querySelector('#cameraStatus');if(label)label.textContent=message;const dot=document.querySelector('#cameraDot');if(dot)dot.classList.toggle('online',online);}
async function checkDrawingService(){const state=document.querySelector('#trackStatus');if(state)state.textContent='Checking local OpenCV connection…';try{const response=await fetch(`${OPENCV_URL}/health`,{cache:'no-store'});if(!response.ok)throw new Error(`HTTP ${response.status}`);const service=await response.json();if(state)state.textContent=service.ok?'OpenCV connected · press Start camera and allow webcam access':'OpenCV service did not confirm readiness';setDrawingStatus(service.ok?'OpenCV is ready · camera has not started yet':'OpenCV service is not ready',Boolean(service.ok));}catch(error){if(state)state.textContent='Cannot reach OpenCV at 127.0.0.1:4174. Start opencv-drawing/server.py, then refresh.';setDrawingStatus('OpenCV connection failed · check the Python service',false);}}
async function beginWebcamDrawing(){const video=document.querySelector('#drawingVideo'),canvas=document.querySelector('#drawingCanvas');if(!video||!canvas)return;const state=document.querySelector('#trackStatus');if(!navigator.mediaDevices?.getUserMedia){if(state)state.textContent='Camera access is unavailable here. Open this page in a browser that allows webcam access.';setDrawingStatus('This browser context cannot access the webcam.',false);return;}try{const health=await fetch(`${OPENCV_URL}/health`);if(!health.ok)throw new Error('OpenCV service is unavailable');}catch{if(state)state.textContent='OpenCV service is not reachable at 127.0.0.1:4174. Start the Python service, then try again.';setDrawingStatus('Python OpenCV service is offline · see setup instructions.',false);return;}try{drawingStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'user',width:{ideal:640},height:{ideal:480}},audio:false});video.srcObject=drawingStream;await video.play();canvas.width=video.videoWidth||640;canvas.height=video.videoHeight||480;canvas.classList.add('active');document.querySelector('.drawing-stage')?.classList.add('camera-on');document.querySelector('#drawingPrompt').hidden=true;document.querySelector('#startCamera').textContent='Stop camera';document.querySelector('#pauseDrawing').disabled=false;drawingPrevious=null;drawingPaused=false;document.querySelector('#pauseDrawing').textContent='Ⅱ Pause drawing';setDrawingStatus('Camera on · frames are processed locally',true);if(state)state.textContent='Camera and OpenCV connected · raise one finger and move it to draw';trackWebcamFrame();}catch(error){if(drawingStream)drawingStream.getTracks().forEach(track=>track.stop());drawingStream=null;video.srcObject=null;document.querySelector('.drawing-stage')?.classList.remove('camera-on');canvas.classList.remove('active');document.querySelector('#drawingPrompt').hidden=false;setDrawingStatus(error.name==='NotAllowedError'?'Camera permission was denied. Allow camera access in your browser settings.':error.name==='NotFoundError'?'No webcam was found. Connect a camera and try again.':`Camera could not start: ${error.message}`,false);if(state)state.textContent=error.name==='NotAllowedError'?'Allow camera permission, then press Start camera again.':'Check the webcam and browser permissions, then retry.';}}
function stopWebcamDrawing(){if(drawingStream)drawingStream.getTracks().forEach(track=>track.stop());drawingStream=null;clearTimeout(drawingLoop);const v=document.querySelector('#drawingVideo');if(v)v.srcObject=null;const c=document.querySelector('#drawingCanvas');if(c)c.classList.remove('active');const sketch=document.querySelector('#sketchCanvas');if(sketch){sketch.classList.remove('active');sketch.hidden=true;}document.querySelector('.drawing-stage')?.classList.remove('camera-on');const handPointer=document.querySelector('#handPointer');if(handPointer)handPointer.hidden=true;const prompt=document.querySelector('#drawingPrompt');if(prompt)prompt.hidden=false;const start=document.querySelector('#startCamera');if(start)start.textContent='Start camera';const pause=document.querySelector('#pauseDrawing');if(pause)pause.disabled=true;drawingPrevious=null;setDrawingStatus('Camera off · press Start camera when you are ready.',false);const track=document.querySelector('#trackStatus');if(track)track.textContent='Camera stopped · your saved drawing stays on this page.';}
