async function startCvCamera(){const video=document.querySelector('#cvCameraVideo'),status=document.querySelector('#cvCameraStatus');if(!video||!navigator.mediaDevices?.getUserMedia){if(status)status.textContent='This browser context cannot access a webcam.';return;}if(status)status.textContent='Connecting to local OpenCV and requesting camera permission…';try{const h=await fetch(`${OPENCV_URL}/health`);if(!h.ok)throw new Error('Python OpenCV service is offline');cvStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'user',width:{ideal:640},height:{ideal:480}},audio:false});video.srcObject=cvStream;await video.play();document.querySelector('#cvCameraStart').disabled=true;document.querySelector('#cvCameraStop').disabled=false;if(status)status.textContent='Camera active · frames are processed locally on this computer.';const overlay=document.querySelector('#cvCameraOverlay');if(overlay)overlay.hidden=true;trackCvCamera();}catch(err){if(cvStream)cvStream.getTracks().forEach(t=>t.stop());cvStream=null;if(status)status.textContent=err.name==='NotAllowedError'?'Camera permission was denied. Allow access in browser settings and retry.':`Could not start camera: ${err.message}. Check Python service and browser permissions.`;}}
