 if(cvCurrentLab==='object-3d'){const obj=document.querySelector('#moleculeObject');if(obj)obj.style.setProperty('--mol-rotate',`${r.x*360}deg`);if(obj)obj.style.transform=`translate(${(r.x-.5)*110}px,${(r.y-.5)*60}px) scale(var(--mol-scale,1)) rotate(var(--mol-rotate,0deg))`;}
